module.exports=[483891,a=>{"use strict";a.s(["CERTIFICATIONS",0,[{id:"cert-01",title:"SEO and Content Strategy Professional Certificate",organization:"IBM",year:"2023",iconColor:"#0f62fe"},{id:"cert-02",title:"Search Engine Optimization Professional Certificate",organization:"Moz",year:"2021",iconColor:"#328aff"},{id:"cert-03",title:"Local SEO Certificate",organization:"BrightLocal",year:"2022",iconColor:"#e6194b"},{id:"cert-04",title:"Claude101 Certificate",organization:"Anthropic",year:"2024",iconColor:"#cc9900"}],"EXPERIENCE_TIMELINE",0,[{id:"exp-01",role:"SEO Strategist & Consultant",company:"Independent / Freelance",period:"2024 - Present",bullets:["Architected semantic SEO strategies and topical authority maps for multiple digital assets, aligning content clusters with search entities to maximize ranking potential and AI-citation readiness.","Formulated and executed semantic SEO strategies and entity-based content architectures for windcave.com and anxivo.com, scaling organic presence and search authority.","Built and scaled local SEO lead-generation systems in competitive US service niches (Junk Removal, RV Repair), optimizing site architecture for localized SERP performance.","Ran competitive intelligence and entity-based content gap analysis to surface and capture high-value ranking opportunities."],analyticalAngle:"Bypasses keyword guesswork to architect robust Entity-Relationship Maps and schema registries, positioning domains for both traditional rankings and AI-citation systems."}],"EXPERTISE_TAGS",0,["Semantic SEO","Entity SEO","Topical Authority","AI Overviews (AIO)","ChatGPT Visibility","Perplexity Optimization","Google Business Profile","Schema Markup","Knowledge Graph Construction","AEO (Answer Engine Optimization)","GEO (Generative Engine Optimization)","Technical SEO","Content Architecture","Local SEO","Google Search Console","Google Analytics (GA4)","SEMrush","Screaming Frog","Moz","Excel Data Modeling"],"FEATURED_PROJECTS",0,[{id:"case-01",title:"Semantic SEO structuring & entity clustering",industry:"FinTech & Payments",challenge:"The client windcave.com faced severe search visibility plateau and fragmented domain equity across its payment product categories, with search crawlers failing to associate their pages with core payment entities.",strategy:"Implemented a robust Semantic SEO architecture. This included mapping out an entity-based topical authority framework, structuring key-value payment schemas, and engineering semantic content clusters to position the domain as an authoritative source in both Google and AI search engines.",execution:["Injected structured JSON-LD schemas linking pages directly to primary Wikidata entity coordinates.","Re-engineered site content architecture into structured topical clusters matching payment search entities.","Optimized payment gateway API references and developer documentation hubs for search agent readability.","Conducted comprehensive entity-based content gaps to build unbreakable topical coverage for critical terms."],results:["+112% increase in organic lead registrations within 9 months of semantic launch","First-page visibility established for high-intent payment solutions and direct AI-search citations","Resolved internal topical cannibalization issues, recapturing lost keyword authority"],technologies:["Wikidata","JSON-LD Schema","Semantic SEO","Ahrefs","Google Search Console"],imageSrc:"https://images.unsplash.com/photo-1460925895917-afdab827c52f?auto=format&fit=crop&w=1200&q=80",ctaText:"Examine semantic strategy"},{id:"case-02",title:"Local SEO systems for competitive service niches",industry:"US Service Niches",challenge:"New brand entrants in hyper-competitive local service niches (Junk Removal, RV Repair) needed rapid localized SERP traction with low advertising spend.",strategy:"Deployed localized SEO systems for competitive service niches, utilizing hyper-nested geographic schemas and structured local business identifiers.",execution:["Optimized multi-location site architectures optimized for localized intent.","Implemented comprehensive Google Business Profile configurations synced with geo-specific landing pages.","Built hyper-local nested citation schemas to trigger Google's local map pack.","Programmatically scaled service-page content architectures mapped to local neighborhood coordinates."],results:["Generated 1,200+ inbound calls with direct attribution tracking","Ranked 12 distinct regional assets inside the Google local map pack","Achieved average 340% ROI across the active local SEO system portfolio"],technologies:["Google Business Profile","Local Citation Building","Nested Schemas","Analytics Mapping","Local SEO Systems"],imageSrc:"https://images.unsplash.com/photo-1560518883-ce09059eeffa?auto=format&fit=crop&w=1200&q=80",ctaText:"Review local lead architecture"},{id:"case-03",title:"Semantic SEO and AI/LLM alignment for a SaaS analytics platform",industry:"SaaS / AI Solutions",challenge:"Azuno, a fast-growing SaaS company specializing in AI-driven analytics, struggled to gain organic traction despite an innovative product. Its content lacked the semantic depth for search engines and AI systems to interpret intent, geo-targeting was weak, and potential customers in its core San Francisco market were missing the brand entirely.",strategy:"Designed a semantic SEO framework tailored to Azuno's needs: reorganized content around entities, context, and relationships to match how LLMs process queries; built localized landing pages and optimized the Google Business Profile to target San Francisco's tech community; and structured content to be machine-readable and easily surfaced in AI-powered search experiences.",execution:["Reorganized existing content around entities, context, and relationships instead of isolated keywords.","Built localized landing pages targeting San Francisco's tech community and optimized the Google Business Profile.","Structured content to be machine-readable and easily surfaced in AI-powered search experiences.","Aligned the broader content strategy with how large language models interpret and surface information, future-proofing the SEO approach."],results:["+120% increase in organic traffic within 4 months",'Top 3 local search rankings for "AI analytics San Francisco" and related geo-keywords',"35% growth in qualified leads from Bay Area businesses","Improved discoverability across AI-driven search platforms, positioning Azuno as a thought leader in the AI/LLM space"],technologies:["Semantic SEO","Entity Optimization","Local SEO","Google Business Profile","LLM Content Alignment"],imageSrc:"https://images.unsplash.com/photo-1551288049-bebda4e38f71?auto=format&fit=crop&w=1200&q=80",ctaText:"Explore the semantic + AI alignment strategy"}],"METRIC_CARDS",0,[{value:"+112%",title:"Organic Lead Growth",description:"Architected semantic entity structuring and topical clustering for windcave.com fintech search categories.",tags:["FinTech","Semantic SEO"]},{value:"1,200+",title:"Inbound Calls Generated",description:"Sourced through optimized regional local SEO system assets in hyper-competitive service niches.",tags:["Local SEO","Lead Gen"]},{value:"340%",title:"Average SEO ROI",description:"High-intent localized search systems built for continuous calls, form-fills, and revenue attribution.",tags:["Data Analytics","Performance"]}],"PHILOSOPHY_STATEMENTS",0,[{lead:"Search engines read entities, not strings.",body:"Traditional search engines crawled simple text sequences. Today, Google's knowledge systems and modern LLMs process real-world concept nodes. When you structure your content around verified entities and properties, you make yourself impossible to ignore."},{lead:"Structure is the language of AI search.",body:"AI models from OpenAI, Anthropic, and Google do not surf web pages like humans. They parse patterns, structured data, and unambiguous assertions. If your expertise is not formatted cleanly into machine-readable knowledge nodes, you remain invisible."},{lead:"SEO must align with business numbers.",body:"Search volume is a vanity metric. True search advisory means tying organic impressions directly to pipeline revenues. My background in corporate sales and market analytics ensures every SEO campaign is built on concrete financial outcomes."}],"STRATEGIST_NAME",0,"Farrukh Abdullah","STRATEGIST_SPECS",0,[{label:"Based in",value:"Faisalabad, Pakistan — working with clients globally"},{label:"Focus",value:"Entity SEO, knowledge graphs, and generative engine optimization (GEO)"},{label:"Status",value:"Currently taking on new projects",statusColor:"#00c2ff"}],"STRATEGIST_TITLE",0,"Semantic SEO Specialist","TESTIMONIALS",0,[{id:"testimonial-01",quote:"I own a coffee shop in Austin, Texas, and we were buried on page three of Google. Farrukh helped us show up in the local pack within weeks. Now new customers literally tell us they found us online. He's approachable, explains things clearly, and delivers results.",name:"Sarah M.",role:"Owner, Coffee Shop",company:"Austin, TX"},{id:"testimonial-02",quote:"Running a small law firm in Chicago, I needed someone who understood how clients search locally. Farrukh rebuilt our SEO strategy from the ground up. Calls from local leads have doubled, and our site finally feels professional. He's the kind of specialist you want in your corner.",name:"David R.",role:"Attorney, Law Firm",company:"Chicago, IL"},{id:"testimonial-03",quote:"I manage a boutique hotel in Miami, and competition here is fierce. Farrukh's geo-targeted SEO gave us visibility in exactly the neighborhoods we wanted. Bookings through organic search are up 35%. He's responsive, detail-oriented, and genuinely cares about outcomes.",name:"Elena P.",role:"Manager, Boutique Hotel",company:"Miami, FL"},{id:"testimonial-04",quote:"Our e-commerce store in Denver was struggling to get traction. Farrukh spotted technical issues and optimized our product pages with semantic SEO. Within three months, organic sales became our main revenue stream. He's not just an SEO guy — he's a strategist.",name:"Mark T.",role:"Owner, E-Commerce Store",company:"Denver, CO"},{id:"testimonial-05",quote:"I run a fitness studio in Seattle, and Farrukh helped us dominate local search. We're now consistently in the top three results, which brought in a steady stream of new members. What I appreciated most was how he explained everything in plain English. Highly recommend.",name:"Jessica L.",role:"Owner, Fitness Studio",company:"Seattle, WA"},{id:"testimonial-06",quote:"As a tech startup founder in San Francisco, I was fascinated by how Farrukh connected semantic SEO with the latest advances in AI. He showed us how search engines increasingly rely on language models to interpret intent, and then tailored our content so it aligned perfectly with those signals. On top of that, his geo-targeting strategy helped us capture local visibility in the Bay Area. The combination of semantic precision and geo focus gave us a real competitive edge.",name:"Michael K.",role:"Founder, Tech Startup",company:"San Francisco, CA"},{id:"testimonial-07",quote:"Farrukh showed us how semantic SEO and geo-targeting could work hand-in-hand with the way AI and language models interpret search intent. His strategy didn't just boost our rankings, it made our content future-proof in an AI-first world.",name:"Margaret Genet",role:"Head of Marketing",company:"Azuno, San Francisco, CA",linkedCaseStudyPath:"/case-studies/azuno"}]])}];

